solution_1:
开数组w[i],b[i],r[i]，分别表示把前i行涂成白、蓝、红需要涂的格子数

设第1行到第i行是白色

第i+1行到第j行是蓝色

则第j+1行到第n行是红色

此时代价为wi+bj−bi+rn−rj

​枚举i,j，取最小值即可
#include<iostream>
#include<algorithm>
using namespace std;
int n,m,ans=0x7fffffff,w[51],b[51],r[51];
string s;
inline int check(char c){
    int tot=0;
    for(int i=0;i<m;++i)
        if(s[i]!=c)++tot;
    return tot;    
}
int main(int argc, char const *argv[])
{
    cin>>n>>m;
    for(int i=1;i<=n;++i){
        cin>>s;
        w[i]=w[i-1]+check('W');
        b[i]=b[i-1]+check('B');
        r[i]=r[i-1]+check('R');
    }
    for(int i=1;i<n-1;++i)
        for(int j=i+1;j<n;++j)
            ans=min(ans,w[i]+b[j]-b[i]+r[n]-r[j]);
    cout<<ans;        
    return 0;
}

solution_2:
主要思想枚举
枚举白与蓝，蓝与红的分界
首先来一个纯暴力，O（n^3*m），不是要求的颜色就++sum （反正n，m<=50）
int main(){
 scanf("%d%d\n",&n,&m);
 for(int i=1;i<=n;i++)gets(a[i]);
 for(int i=2;i<n;i++){//i指下一种颜色从第i行开始
  for(int j=i+1;j<=n;j++){
   sum=0;
   for(int x=1;x<i;x++)
    for(int y=0;y<m;y++)
     if(a[x][y]!='W')++sum;//计算要涂颜色的次数（白）
   for(int x=i;x<j;x++)
    for(int y=0;y<m;y++)
     if(a[x][y]!='B')++sum;//（红）
   for(int x=j;x<=n;x++)
    for(int y=0;y<m;y++)
     if(a[x][y]!='R')++sum;//（蓝）
   if(sum<ans)ans=sum;//sum与ans的值的更改务必看清楚！！！
  }
 }
 printf("%d",ans);
 return 0;
}```
细心的你应该已经发现了，每一行都被计算多次  
可以预处理下结果，枚举时直接调用  
复杂度降至O（n^3）  
```cpp
#include<iostream>
#include<cstdio>
#include<cstring>
using namespace std;
char a[101][101];
int W[101],B[101],R[101];
int n,m,ans=0x7fffffff,sum;
int main(){
 scanf("%d%d\n",&n,&m);
 for(int i=1;i<=n;i++)gets(a[i]);
 for(int i=1;i<=n;i++)
  for(int j=0;j<m;j++){
   if(a[i][j]!='W')W[i]++;
   if(a[i][j]!='B')B[i]++;
   if(a[i][j]!='R')R[i]++;
  }
 for(int i=2;i<n;i++){
  for(int j=i+1;j<=n;j++){
   sum=0;
   for(int x=1;x<i;x++)sum+=W[x];
   for(int x=i;x<j;x++)sum+=B[x];
   for(int x=j;x<=n;x++)sum+=R[x];
   if(sum<ans)ans=sum;
  }
 }
 printf("%d",ans);
 return 0;
}
